package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class GradeSevenFractionQuantityScopeTest {
 private static Question question(String total,String n,String d){return new Question(QuantityFractionCheck.ID,total+"의 "+n+"/"+d+"은 얼마인가요?","poison","999");}
 @Test public void sevenRouteNaturallyIncludesRationalPartsWhileSixAndEarlierDiagramsRemain(){
  var pack=GlobalCurriculum.packs("NA").stream().filter(p->p.id.equals("na-nied-primary-2024-v1")).findFirst().orElseThrow();assertTrue(pack.inGrade(QuantityFractionCheck.ID,7));var seven=GlobalCurriculum.limits(pack.id,QuantityFractionCheck.ID,7);var six=GlobalCurriculum.limits(pack.id,QuantityFractionCheck.ID,6);assertTrue(seven.quantityRationalParts());assertFalse(six.quantityRationalParts());Generator generator=new Generator(new Random(356));List<String>recent=new ArrayList<>();boolean rational=false,improper=false;
  for(int i=0;i<100;i++){Question q=generator.next(QuantityFractionCheck.ID,recent,false,seven);assertFalse(recent.contains(q.signature()));recent.add(q.signature());var v=QuantityFractionCheck.readGeneral(q);assertNotNull(v);assertTrue(seven.allows(q));rational|=!v.value().isInteger();improper|=v.numerator().compareTo(v.denominator())>0;assertTrue(v.total().compareTo(Rational.of(100))<=0);assertEquals("",q.answerFormat);assertEquals(!v.value().isInteger(),q.decimal);assertEquals(!v.value().isInteger(),FractionInput.defaultFraction(q));assertTrue(new Checker().check(q,List.of(),List.of(v.value().n+"/"+v.value().d)).correct());assertEquals(5,HelpPlan.forQuestion(q).size());assertFalse(HelpPlan.forQuestion(q).canTransfer());}assertTrue(rational);assertTrue(improper);
  for(int i=0;i<50;i++){Question q=generator.next(QuantityFractionCheck.ID,List.of(),false,six);assertNotNull(QuantityFractionCheck.read(q));assertFalse(FractionInput.defaultFraction(q));assertTrue(QuantityFractionCheck.readGeneral(q).value().isInteger());}var early=GlobalCurriculum.limits("england-primary-2021-v1",QuantityFractionCheck.ID,2);Question objects=QuantityFractionPictures.create(Catalog.get(QuantityFractionCheck.ID),3,4,4,"objects");assertTrue(early.allows(objects));assertEquals("fractionQuantityObjects",objects.diagram.type);assertEquals(5,HelpPlan.forQuestion(objects).size());
 }
 @Test public void normalFreshSevenSupplyAllowsExactNumberFormsWithoutForcingFractionAnswers(){
  var limits=GlobalCurriculum.limits("na-nied-primary-2024-v1",QuantityFractionCheck.ID,7);Generator generator=new Generator(new Random(356710));List<String>recent=new ArrayList<>();Question integer=null,terminating=null;
  for(int i=0;i<500&&(integer==null||terminating==null);i++){
   Question q=generator.next(QuantityFractionCheck.ID,recent,false,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());assertTrue(limits.allows(q));Rational value=QuantityFractionCheck.readGeneral(q).value();
   assertEquals("",q.answerFormat);assertEquals(!value.isInteger(),q.decimal);assertEquals(!value.isInteger(),FractionInput.defaultFraction(q));
   if(integer==null&&value.isInteger()&&value.compareTo(Rational.ZERO)>0)integer=q;
   if(terminating==null&&!value.isInteger()&&!value.decimalText().contains("/"))terminating=q;
  }
  assertNotNull("Normal NA7 supply must include an integer result",integer);assertNotNull("Normal NA7 supply must include an exact terminating noninteger result",terminating);Checker checker=new Checker();
  Rational whole=QuantityFractionCheck.readGeneral(integer).value();assertFalse(FractionInput.defaultFraction(integer));assertFalse(integer.decimal);assertTrue(checker.check(integer,List.of(),List.of(whole.n.toString())).correct());assertTrue(checker.check(integer,List.of(),List.of(whole.n+".0")).correct());assertTrue(checker.check(integer,List.of(),List.of(whole.n+"/1")).correct());
  Rational part=QuantityFractionCheck.readGeneral(terminating).value();assertTrue(FractionInput.defaultFraction(terminating));assertTrue(terminating.decimal);assertTrue(checker.check(terminating,List.of(),List.of(part.toString())).correct());assertTrue(checker.check(terminating,List.of(),List.of(part.decimalText())).correct());assertFalse(checker.check(terminating,List.of(),List.of(part.add(Rational.ONE).decimalText())).correct());
 }
 @Test public void generalPublicOperandsAndFiveRationalBlankFramesIgnoreSavedAuthority(){
  String[][]cases={{"5","2","3","10/3"},{"1/2","3","4","3/8"},{"(1/2)","3","4","3/8"},{"0.50","2","3","1/3"},{"0","7","3","0"},{"25","0","3","0"},{"5","3","3","5"},{"5","5","3","25/3"},{"12345","2","7","24690/7"},{"1.25","3","2","15/8"}};
  for(String[]c:cases){Question q=question(c[0],c[1],c[2]);StudyGuide stored=new StudyGuide().step("private","private","","999");q.studyGuide=stored;String prompt=q.prompt;var g=QuantityFractionCheck.readGeneral(q);assertNotNull(prompt,g);assertEquals(c[0],g.totalRaw());assertEquals(c[1],g.numeratorRaw());assertEquals(c[2],g.denominatorRaw());assertEquals(Expression.number(c[3]),g.value());assertTrue(new Checker().check(q,List.of(),List.of(c[3])).correct());HelpPlan help=HelpPlan.forQuestion(q);assertEquals(5,help.size());assertFalse(help.canTransfer());List<String>values=List.of(g.total().toString(),g.numerator().toString(),g.denominator().toString(),g.part().toString(),g.value().toString());for(int i=0;i<5;i++){assertTrue(help.step(i).accepts(values.get(i)));assertEquals("",help.step(i).after);assertTrue(help.step(i).options.isEmpty());}assertSame(stored,q.studyGuide);assertEquals("999",stored.frames.get(0).expected);assertEquals(prompt,q.prompt);assertEquals("poison",q.expression);assertArrayEquals(new String[]{"999"},q.answers);}
  Question cm=new Question(QuantityFractionCheck.ID,"0.5 cm의 2/3은 몇 cm인가요?","poison","999");assertEquals("cm",QuantityFractionCheck.readGeneral(cm).unit());assertTrue(new Checker().check(cm,List.of(),List.of("1/3")).correct());
 }
 @Test public void legacyDraftExactFramesAndFullPublicWorkFormatsAndPartErrorsStayManual(){
  Question old=QuantityFractionPictures.create(Catalog.get(QuantityFractionCheck.ID),2,3,5,"number");HelpPlan h=HelpPlan.forQuestion(old);List<String>values=List.of("15","2","3","5","10");List<String>before=List.of("전체 수 = ","분자 = ","분모 = ","전체 수 ÷ 분모 = ","한 부분 × 분자 = ");for(int i=0;i<5;i++)assertEquals(before.get(i),h.step(i).before);HelpPlan.Draft draft=new HelpPlan.Draft();draft.questionId=old.id;draft.teachingVersion="fraction-concept-relations-v1";draft.stage=5;draft.entries=new ArrayList<>(values);var restored=h.restore(draft.copy(),old.id);assertEquals(5,restored.stage);assertEquals(values,restored.entries.subList(0,5));assertEquals("10",h.enteredAnswer(restored));
  Question q=question("5","2","3");Checker checker=new Checker();assertTrue(checker.check(q,List.of("5*(2/3)=10/3"),List.of("10/3"),List.of(Checker.StepKind.FULL)).correct());assertTrue(checker.check(q,List.of("5/3=5/3"),List.of("10/3"),List.of(Checker.StepKind.PARTIAL)).correct());assertFalse(checker.check(q,List.of("999=999"),List.of("10/3"),List.of(Checker.StepKind.FULL)).correct());assertEquals(1,FractionInput.errorPart(q,"11/3"));assertEquals(2,FractionInput.errorPart(q,"10/4"));assertEquals(0,FractionInput.errorPart(q,"20/6"));assertEquals(0,FractionInput.errorPart(q,"11/4"));q.answerFormat="fraction";assertEquals(Checker.Status.INPUT_NEEDED,checker.check(q,List.of(),List.of("")).status);assertEquals(Checker.Status.INPUT_NEEDED,checker.check(q,List.of(),List.of("3.333")).status);assertTrue(checker.check(q,List.of(),List.of("20/6")).correct());q.kind="reduced";assertEquals(Checker.Status.INPUT_NEEDED,checker.check(q,List.of(),List.of("20/6")).status);assertTrue(checker.check(q,List.of(),List.of("10/3")).correct());
 }
 @Test public void invalidPublicPromptCannotFallBackAndSourceGuardsStayGeneral(){
  String large="123456789012345678901234567890";Question big=question(large,large,"1");assertNotNull(QuantityFractionCheck.readGeneral(big));assertTrue(new Checker().checkSteps(big,List.of(large+"*("+large+"/1)"),List.of(Checker.StepKind.FULL)).correct());
  Question poisoned=question("5","2","3");poisoned.expression="999*(1/999)";poisoned.answers=new String[]{"-999"};assertTrue(GlobalCurriculum.limits("na-nied-primary-2024-v1",QuantityFractionCheck.ID,7).allows(poisoned));assertFalse(GlobalCurriculum.limits("na-nied-primary-2024-v1",QuantityFractionCheck.ID,6).allows(poisoned));
  for(String[]c:new String[][]{{"-1","2","3"},{"5","-1","3"},{"5","1","0"},{"1/0","1","2"},{"1e2","1","2"},{"0.0000000000001","1","2"},{"1".repeat(31),"1","2"},{"1","1".repeat(31),"2"},{"((1/2))","1","2"}}){Question q=question(c[0],c[1],c[2]);q.studyGuide=new StudyGuide().step("private","private","","999");assertNull(QuantityFractionCheck.readGeneral(q));assertNull(HelpPlan.forQuestion(q));assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(q,List.of(),List.of("999")).status);}
  assertNull(QuantityFractionCheck.readGeneral(null));assertNull(QuantityFractionCheck.guide(null));assertNull(QuantityFractionCheck.workQuestion(null));assertEquals(0,QuantityFractionCheck.errorPart(null,"1/2"));assertEquals(Checker.Status.INPUT_NEEDED,QuantityFractionCheck.check(null,List.of("1")).status);assertFalse(GlobalCurriculum.limits("kr-national",QuantityFractionCheck.ID,7).quantityRationalParts());try{new CurriculumLimits("quantityRationalParts=maybe");fail();}catch(IllegalArgumentException expected){}
 }
 @Test public void legitimateLargeOutputsAndAllFiveEntriesRemainReachableWithinDedicatedBounds(){
  String a="9".repeat(30);Question integer=question(a,a,"1");var iv=QuantityFractionCheck.readGeneral(integer);assertEquals(60,iv.value().toString().length());assertTrue(new Checker().check(integer,List.of(),List.of(iv.value().toString())).correct());
  String power="8"+"0".repeat(29),b="3"+"0".repeat(28)+"1",d="7"+"0".repeat(28)+"3";Question rational=question(power+"/"+b,power,d);var rv=QuantityFractionCheck.readGeneral(rational);assertNotNull(rv);assertEquals(121,rv.value().toString().length());rational.answerFormat="fraction";assertTrue(new Checker().check(rational,List.of(),List.of(rv.value().toString())).correct());assertEquals(0,FractionInput.errorPart(rational,rv.value().toString()));
  for(Question q:List.of(integer,rational)){var v=QuantityFractionCheck.readGeneral(q);HelpPlan h=HelpPlan.forQuestion(q);List<String>entries=List.of(v.total().toString(),v.numerator().toString(),v.denominator().toString(),v.part().toString(),v.value().toString());for(int i=0;i<5;i++)assertTrue(h.step(i).accepts(entries.get(i)));HelpPlan.Draft done=h.restore(null,q.id);done.stage=5;done.entries=new ArrayList<>(entries);assertEquals(v.value().toString(),h.enteredAnswer(done));assertFalse(h.canTransfer());}
  for(String raw:List.of(java.math.BigInteger.ONE.shiftLeft(512).toString(),"1".repeat(241),"1e2","1+1","((1))","0.0000000000001","1/0"))assertNull(raw,QuantityFractionCheck.numericInput(raw));assertEquals(Rational.of(-1,2),QuantityFractionCheck.numericInput("−1/2"));
  Question ordinary=new Question("fracMul","(1/2) × (1/2)","1/2*1/2","1/4");assertFalse(HelpPlan.forQuestion(ordinary).step(0).accepts("0".repeat(31)+"1"));
  Question form=question("2","1","4");form.answerFormat="decimal";assertTrue(new Checker().check(form,List.of(),List.of("0.5")).correct());assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(form,List.of(),List.of("1/2")).status);form.answerFormat="decimalValue";assertTrue(new Checker().check(form,List.of(),List.of("0.5")).correct());assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(form,List.of(),List.of("1/2")).status);form.answerFormat="hundredthsFraction";assertTrue(new Checker().check(form,List.of(),List.of("50/100")).correct());assertEquals(Checker.Status.WRONG_ANSWER,new Checker().check(form,List.of(),List.of("1/2")).status);
 }
}
